WITH valid AS (SELECT *, ROUND(amount, 2) AS amount_rounded, CASE WHEN method IN ('card', 'promptpay') THEN 'Group A' ELSE 'Other' END AS method_group, COALESCE(method, 'N/A') AS method_clean FROM payments WHERE status = 'SUCCESS') SELECT * FROM (SELECT status, method, amount_rounded FROM valid) src PIVOT (AVG(amount_rounded) FOR method IN ('promptpay' AS promptpay, 'cash' AS cash));
